/* From Uiverse.io by Coderlab05 - Source: Coderlab05 - Tags: button, #button */
.__UIV_SCOPE__ .button {
  all: unset;
  width: 100px;
  height: 30px;
  font-size: 16px;
  background: transparent;
  border: none;
  position: relative;
  color: #f0f0f0;
  cursor: pointer;
  z-index: 1;
  padding: 10px 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  white-space: nowrap;
  user-select: none;
  -webkit-user-select: none;
  touch-action: manipulation;
}

.__UIV_SCOPE__ .button::after,
.__UIV_SCOPE__ .button::before {
  content: '';
  position: absolute;
  bottom: 0;
  right: 0;
  z-index: -99999;
  transition: all .4s;
}

.__UIV_SCOPE__ .button::before {
  transform: translate(0%, 0%);
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg,#ff0e5e,rgb(15, 159, 255));
  border-radius: 10px;
}

.__UIV_SCOPE__ .button::after {
  transform: translate(10px, 10px);
  width: 35px;
  height: 35px;
  background: #ffffff15;
  backdrop-filter: blur(5px);
  -webkit-backdrop-filter: blur(5px);
  border-radius: 50px;
}

.__UIV_SCOPE__ .button:hover::before {
  transform: translate(5%, 20%);
  width: 110%;
  height: 110%;
}

.__UIV_SCOPE__ .button:hover::after {
  border-radius: 10px;
  transform: translate(0, 0);
  width: 100%;
  height: 100%;
}

.__UIV_SCOPE__ .button:active::after {
  transition: 0s;
  transform: translate(0, 5%);
}
